/* ============================================
   Orchard — Premium Tech E-Commerce Store
   Global Stylesheet
   ============================================ */

/* CSS Variables */
:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #0077ed;
  --color-border: #d2d2d7;
  --color-badge-bg: #1d1d1f;
  --color-badge-text: #ffffff;
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --max-width: 1024px;
  --header-height: 48px;
  --transition: 0.25s ease;
}

/* Reset & Base */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Header / Navigation
   ============================================ */

.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  height: var(--header-height);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.021em;
  color: var(--color-text);
  text-decoration: none;
}

.logo:hover {
  text-decoration: none;
  color: var(--color-text);
}

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}

.nav-links a {
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
  color: var(--color-text);
  opacity: 0.8;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.nav-links a.active {
  opacity: 1;
  font-weight: 500;
}

.mobile-menu-btn {
  display: none;
  width: 30px;
  height: 30px;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
}

.mobile-menu-btn span {
  display: block;
  height: 1px;
  background: var(--color-text);
  width: 18px;
}

/* ============================================
   Ribbon Banner
   ============================================ */

.ribbon-banner {
  background: var(--color-bg-secondary);
  text-align: center;
  padding: 12px 22px;
  font-size: 12px;
  line-height: 1.33341;
  letter-spacing: -0.01em;
  color: var(--color-text);
}

.ribbon-banner a {
  color: var(--color-link);
}

/* ============================================
   Typography Helpers
   ============================================ */

.section-heading {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.1;
  text-align: center;
  margin-bottom: 8px;
}

.section-subheading {
  font-size: 21px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.19048;
  text-align: center;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
}

.section-heading-small {
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -0.021em;
  line-height: 1.14286;
  text-align: center;
  margin-bottom: 6px;
}

.section-subheading-small {
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -0.022em;
  line-height: 1.47059;
  text-align: center;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

/* ============================================
   Carousel System
   ============================================ */

.carousel-section {
  padding: 48px 0;
  overflow: hidden;
}

.carousel-header {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
  margin-bottom: 20px;
}

.carousel-header .section-heading,
.carousel-header .section-heading-small {
  text-align: left;
  margin-bottom: 4px;
}

.carousel-header .section-subheading,
.carousel-header .section-subheading-small {
  text-align: left;
  margin-bottom: 0;
}

.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.carousel-track-container {
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 8px;
}

.carousel-track-container::-webkit-scrollbar {
  display: none;
}

.carousel-track {
  display: flex;
  gap: 20px;
  padding: 4px 0;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  cursor: pointer;
  transition: opacity var(--transition), transform var(--transition);
  opacity: 0;
  pointer-events: none;
}

.carousel-wrapper:hover .carousel-arrow,
.carousel-wrapper:focus-within .carousel-arrow {
  opacity: 1;
  pointer-events: auto;
}

.carousel-arrow.prev {
  left: 6px;
}

.carousel-arrow.next {
  right: 6px;
}

.carousel-arrow:hover {
  transform: translateY(-50%) scale(1.08);
}

.carousel-arrow svg {
  width: 18px;
  height: 18px;
  fill: var(--color-text);
}

/* Product Card (standard) */
.product-card {
  flex: 0 0 320px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform var(--transition), box-shadow var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.product-card-image {
  height: 220px;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.product-card-image .placeholder-icon {
  font-size: 64px;
  opacity: 0.25;
}

.product-card-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 4px 10px;
  border-radius: 12px;
  text-transform: uppercase;
}

.product-card-body {
  padding: 20px;
}

.product-card-name {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.022em;
  margin-bottom: 4px;
}

.product-card-tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.42857;
  margin-bottom: 12px;
  min-height: 40px;
}

.product-card-price {
  font-size: 15px;
  font-weight: 400;
  color: var(--color-text);
  margin-bottom: 2px;
}

.product-card-monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
}

.product-card-actions {
  display: flex;
  gap: 20px;
}

.product-card-actions a {
  font-size: 14px;
  color: var(--color-link);
}

/* Compact card variant */
.compact-card {
  flex: 0 0 260px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform var(--transition), box-shadow var(--transition);
}

.compact-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.compact-card .product-card-image {
  height: 180px;
}

.compact-card .product-card-body {
  padding: 16px;
}

.compact-card .product-card-name {
  font-size: 15px;
}

.compact-card .product-card-price {
  font-size: 14px;
}

/* Info card (help, difference, etc.) */
.info-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  padding: 28px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform var(--transition), box-shadow var(--transition);
}

.info-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.info-card-icon {
  font-size: 36px;
  margin-bottom: 16px;
}

.info-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.022em;
  margin-bottom: 6px;
}

.info-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.42857;
}

/* ============================================
   Hero Product Showcase (Homepage)
   ============================================ */

.hero-showcase {
  padding: 60px 22px;
  text-align: center;
  background: var(--color-bg);
}

.hero-showcase-title {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.08349;
  margin-bottom: 10px;
}

.hero-showcase-subtitle {
  font-size: 24px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.16667;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

.hero-showcase-ctas {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-showcase-ctas a {
  font-size: 17px;
  color: var(--color-link);
}

/* Product Grid (large tiles) */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  max-width: 1260px;
  margin: 0 auto;
  padding: 12px;
}

.product-tile {
  position: relative;
  min-height: 560px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding-top: 56px;
  text-align: center;
  background: var(--color-bg-secondary);
  transition: transform var(--transition);
}

.product-tile:hover {
  transform: scale(1.005);
}

.product-tile.dark {
  background: #1d1d1f;
  color: #fff;
}

.product-tile.dark .product-tile-tagline {
  color: rgba(255, 255, 255, 0.7);
}

.product-tile.dark .product-tile-ctas a {
  color: #2997ff;
}

.product-tile-name {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.1;
  margin-bottom: 8px;
}

.product-tile-tagline {
  font-size: 21px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.19048;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  max-width: 400px;
  padding: 0 20px;
}

.product-tile-ctas {
  display: flex;
  gap: 24px;
  margin-bottom: 40px;
}

.product-tile-ctas a {
  font-size: 17px;
  color: var(--color-link);
}

.product-tile-image {
  width: 100%;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 40px;
}

.product-tile-image .placeholder-icon {
  font-size: 120px;
  opacity: 0.2;
}

/* Tile gradient variants */
.product-tile.gradient-phone {
  background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%);
}

.product-tile.gradient-laptop {
  background: linear-gradient(180deg, #f5f5f7 0%, #e3e3e8 100%);
}

.product-tile.gradient-tablet {
  background: linear-gradient(180deg, #f5f5f7 0%, #eae4f5 100%);
}

.product-tile.gradient-earbuds {
  background: linear-gradient(180deg, #f5f5f7 0%, #e4eaf5 100%);
}

.product-tile.gradient-trade {
  background: linear-gradient(180deg, #f5f5f7 0%, #f0ece4 100%);
}

/* ============================================
   Entertainment Tabs
   ============================================ */

.entertainment-section {
  padding: 60px 22px;
  background: var(--color-bg);
}

.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 32px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.entertainment-tab {
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -0.022em;
  color: var(--color-text-secondary);
  padding: 8px 0;
  border-bottom: 2px solid transparent;
  transition: color var(--transition), border-color var(--transition);
  cursor: pointer;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}

.entertainment-tab:hover {
  color: var(--color-text);
}

.entertainment-tab.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
  font-weight: 500;
}

.entertainment-panels {
  max-width: var(--max-width);
  margin: 0 auto;
}

.entertainment-panel {
  display: none;
}

.entertainment-panel.active {
  display: block;
}

.entertainment-panel .carousel-track {
  gap: 20px;
}

.entertainment-card {
  flex: 0 0 380px;
  height: 240px;
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  background: var(--color-bg-secondary);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 24px;
  transition: transform var(--transition);
}

.entertainment-card:hover {
  transform: scale(1.02);
}

.entertainment-card-title {
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.021em;
  color: #fff;
  margin-bottom: 6px;
  text-shadow: 0 1px 4px rgba(0,0,0,0.4);
}

.entertainment-card-cta {
  font-size: 14px;
  color: #fff;
  text-shadow: 0 1px 4px rgba(0,0,0,0.4);
}

.entertainment-card-cta:hover {
  text-decoration: underline;
}

/* ============================================
   Store Hero
   ============================================ */

.store-hero {
  padding: 60px 22px 40px;
  text-align: center;
  background: var(--color-bg);
}

.store-hero-title {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.08349;
  margin-bottom: 12px;
}

.store-hero-subtitle {
  font-size: 21px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.19048;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

.store-hero-ctas {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}

.store-hero-ctas a {
  font-size: 17px;
  color: var(--color-link);
}

/* ============================================
   Product Icon Bar
   ============================================ */

.icon-bar-section {
  padding: 24px 0;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

.icon-bar-track {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-text);
  transition: opacity var(--transition);
}

.icon-bar-item:hover {
  opacity: 0.8;
  text-decoration: none;
}

.icon-bar-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.icon-bar-label {
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
}

/* ============================================
   Category Hero
   ============================================ */

.category-hero {
  padding: 80px 22px 48px;
  text-align: center;
  background: var(--color-bg);
}

.category-hero-title {
  font-size: 56px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.07143;
  margin-bottom: 12px;
}

.category-hero-subtitle {
  font-size: 24px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.16667;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

/* ============================================
   Sticky Section Nav (Category Pages)
   ============================================ */

.section-nav {
  position: sticky;
  top: var(--header-height);
  z-index: 900;
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  padding: 12px 0;
}

.section-nav-track {
  display: flex;
  gap: 28px;
  justify-content: center;
  flex-wrap: wrap;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.section-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-text);
  opacity: 0.7;
  transition: opacity var(--transition);
  white-space: nowrap;
}

.section-nav a:hover {
  opacity: 1;
  text-decoration: none;
}

/* ============================================
   Shopping Guides / Ways to Save / Special Stores
   ============================================ */

.guides-section,
.save-section,
.special-stores-section {
  padding: 60px 22px;
  background: var(--color-bg);
}

.guides-section.alt-bg,
.save-section.alt-bg,
.special-stores-section.alt-bg {
  background: var(--color-bg-secondary);
}

.guides-grid,
.save-grid,
.stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.guide-card,
.save-card,
.store-card {
  background: var(--color-bg);
  border-radius: var(--radius-md);
  padding: 28px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform var(--transition), box-shadow var(--transition);
}

.guide-card:hover,
.save-card:hover,
.store-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.guide-card-title,
.save-card-title,
.store-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.022em;
  margin-bottom: 6px;
}

.guide-card-desc,
.save-card-desc,
.store-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.42857;
}

/* ============================================
   Brand Collaboration
   ============================================ */

.brand-collab-section {
  padding: 60px 22px;
  background: var(--color-bg-secondary);
  text-align: center;
}

.brand-collab-content {
  max-width: 600px;
  margin: 0 auto;
}

.brand-collab-title {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.1;
  margin-bottom: 12px;
}

.brand-collab-subtitle {
  font-size: 21px;
  font-weight: 400;
  letter-spacing: -0.021em;
  line-height: 1.19048;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

.brand-collab-desc {
  font-size: 17px;
  color: var(--color-text-secondary);
  line-height: 1.47059;
}

/* ============================================
   Quick Links
   ============================================ */

.quick-links-section {
  padding: 40px 22px;
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
}

.quick-links {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  max-width: var(--max-width);
  margin: 0 auto;
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 18px;
  border-radius: 980px;
  background: var(--color-bg-secondary);
  font-size: 14px;
  font-weight: 400;
  color: var(--color-text);
  transition: background var(--transition);
}

.quick-link:hover {
  background: #e8e8ed;
  text-decoration: none;
}

/* ============================================
   Setup / Experience Section
   ============================================ */

.setup-section,
.experience-section {
  padding: 60px 22px;
  background: var(--color-bg-secondary);
  text-align: center;
}

.setup-section .section-subheading,
.experience-section .section-subheading {
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* ============================================
   Footer
   ============================================ */

.site-footer {
  background: var(--color-bg-secondary);
  padding: 40px 22px 24px;
  font-size: 12px;
  line-height: 1.33341;
  color: var(--color-text-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.footer-column h4 {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
